BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=public,extensions;
SELECT no_plan();
INSERT INTO public.contacts(id,phone_e164,contact_type) VALUES('fd276000-0000-4000-8000-000000000071','+61400276071','OTHER');
INSERT INTO public.owned_numbers(id,phone_e164,provider) VALUES('fd276000-0000-4000-8000-000000000072','+61400276072','TWILIO');
INSERT INTO public.conversations(id,contact_id,owned_number_id) VALUES('fd276000-0000-4000-8000-000000000073','fd276000-0000-4000-8000-000000000071','fd276000-0000-4000-8000-000000000072');
INSERT INTO public.messages(id,conversation_id,direction,body,from_number_e164,to_number_e164,status) VALUES('fd276000-0000-4000-8000-000000000074','fd276000-0000-4000-8000-000000000073','INBOUND','Retained conversation history','+61400276071','+61400276072','RECEIVED');
SELECT set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
SET LOCAL ROLE authenticated;
SELECT throws_ok($$DELETE FROM public.messages WHERE id='fd276000-0000-4000-8000-000000000074'$$,'42501','permission denied for table messages','AdminStaff cannot delete a conversation message');
SELECT is((SELECT body FROM public.messages WHERE id='fd276000-0000-4000-8000-000000000074'),'Retained conversation history','denied deletion preserves readable message history');
SELECT throws_ok($$DELETE FROM public.conversations WHERE id='fd276000-0000-4000-8000-000000000073'$$,'42501','permission denied for table conversations','AdminStaff cannot erase history through conversation deletion');
SELECT throws_ok($$DELETE FROM public.contacts WHERE id='fd276000-0000-4000-8000-000000000071'$$,'42501','Message deletion is not allowed','contact deletion cannot cascade through message history');
SELECT throws_ok($$SELECT public.enqueue_imessage_command('delete_message','fd276000-0000-4000-8000-000000000074',NULL,'{}','Delete request')$$,'23514',NULL,'AdminStaff cannot queue provider message deletion');
SELECT throws_ok($$SELECT public.enqueue_imessage_command('delete_chat',NULL,'fd276000-0000-4000-8000-000000000073','{}','Delete request')$$,'23514',NULL,'AdminStaff cannot queue provider chat deletion');
SELECT lives_ok($$SELECT public.enqueue_imessage_command('mark_chat_read',NULL,'fd276000-0000-4000-8000-000000000073','{}')$$,'ordinary provider controls remain available');
SELECT is((SELECT count(*) FROM public.messages WHERE id='fd276000-0000-4000-8000-000000000074'),1::bigint,'message survives every denied deletion path');
SELECT * FROM finish();
ROLLBACK;
